/* Service worker for the Ultimate Hindu Devotional Collection (generated by hooks/generate.py).
 *
 *  - App shell (home, index, finder, styles, scripts, search data) is precached per version.
 *  - Pages: network-first (fresh when online), falling back to the saved copy, then /offline/.
 *  - Static files: stale-while-revalidate.  Google Fonts: cache-first.
 *  - "abp-pages" is NOT versioned, so categories saved for offline survive app updates.
 */
const VERSION = "__VERSION__";
const SHELL_CACHE = `abp-shell-${VERSION}`;
const PAGES_CACHE = "abp-pages";
const STATIC_CACHE = `abp-static-${VERSION}`;
const FONT_CACHE = "abp-fonts";
const SHELL = __SHELL__;
const SCOPE = new URL("./", self.location).href;
const OFFLINE_URL = new URL("offline/", SCOPE).href;
const NETWORK_TIMEOUT_MS = 6000;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) =>
      Promise.all(
        SHELL.map((path) =>
          cache.add(new Request(new URL(path, SCOPE).href, { cache: "reload" })).catch((err) =>
            console.warn("[sw] precache failed", path, err)
          )
        )
      )
    )
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) =>
        (k.startsWith("abp-shell-") && k !== SHELL_CACHE) ||
        (k.startsWith("abp-static") && k !== STATIC_CACHE)
      ).map((k) => caches.delete(k)));
      if (self.registration.navigationPreload) await self.registration.navigationPreload.enable();
      await self.clients.claim();
    })()
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data && event.data.type === "VERSION") event.source.postMessage({ type: "VERSION", version: VERSION });
});

const isPage = (url, request) =>
  request.mode === "navigate" || url.pathname.endsWith("/") || url.pathname.endsWith(".html");

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), ms));
}

async function matchAny(request) {
  const hit = (await caches.match(request, { ignoreSearch: true })) || null;
  if (hit) return hit;
  // "…/page" and "…/page/index.html" are the same page
  const url = new URL(request.url);
  if (url.pathname.endsWith("/")) return caches.match(url.href + "index.html", { ignoreSearch: true });
  if (url.pathname.endsWith("/index.html")) return caches.match(url.href.replace(/index\.html$/, ""), { ignoreSearch: true });
  return null;
}

async function pageStrategy(event) {
  const { request } = event;
  try {
    const preload = event.preloadResponse ? await event.preloadResponse : null;
    const response = preload || (await Promise.race([fetch(request), timeout(NETWORK_TIMEOUT_MS)]));
    if (response && response.ok && response.type === "basic") {
      const copy = response.clone();
      caches.open(PAGES_CACHE).then((c) => c.put(request.url.split("#")[0].split("?")[0], copy));
    }
    return response;
  } catch (err) {
    const cached = await matchAny(request);
    if (cached) return cached;
    if (request.mode === "navigate" && (await caches.match(OFFLINE_URL))) {
      // redirect so the offline page keeps correct relative links; remember where the reader wanted to go
      return Response.redirect(`${OFFLINE_URL}?from=${encodeURIComponent(request.url)}`, 302);
    }
    return new Response("Offline", { status: 503, headers: { "Content-Type": "text/plain" } });
  }
}

async function staleWhileRevalidate(event, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await matchAny(event.request);
  const network = fetch(event.request)
    .then((response) => {
      if (response && (response.ok || response.type === "opaque")) cache.put(event.request, response.clone());
      return response;
    })
    .catch(() => cached || new Response("", { status: 504, statusText: "Offline" }));
  if (cached) {
    event.waitUntil(network.catch(() => {}));
    return cached;
  }
  return network;
}

async function cacheFirst(event, cacheName) {
  const cached = await caches.match(event.request);
  if (cached) return cached;
  const response = await fetch(event.request);
  if (response && (response.ok || response.type === "opaque")) (await caches.open(cacheName)).put(event.request, response.clone());
  return response;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);

  if (url.origin === "https://fonts.googleapis.com") return event.respondWith(staleWhileRevalidate(event, FONT_CACHE));
  if (url.origin === "https://fonts.gstatic.com") return event.respondWith(cacheFirst(event, FONT_CACHE));
  if (!request.url.startsWith(SCOPE)) return; // YouTube and other external links: browser default

  if (url.pathname.endsWith("/sw.js")) return;
  if (isPage(url, request)) return event.respondWith(pageStrategy(event));
  event.respondWith(staleWhileRevalidate(event, STATIC_CACHE));
});
